t;td CLASS=&quot;gauche&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barbare-Unchained.html#POUVOIRDERAGE&quot; title=&quot;Le barbare unchained&quot;&gt;pouvoir de rage&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Barbare-Unchained.html#VOLONTEINDOMPTABLE&quot; title=&quot;Le barbare unchained&quot;&gt;volont&#233; indomptable&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;15&lt;/td&gt;&lt;td&gt;+15/+10/+5&lt;/td&gt;&lt;td&gt;+5&lt;/td&gt;&lt;td&gt;+9&lt;/td&gt;&lt;td&gt;+5&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barbare-Unchained.html#SENSDUDANGER&quot; title=&quot;Le barbare unchained&quot;&gt;sens du danger&lt;/a&gt; +5&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;16&lt;/td&gt;&lt;td&gt;+16/+11/+6/+1&lt;/td&gt;&lt;td&gt;+5&lt;/td&gt;&lt;td&gt;+10&lt;/td&gt;&lt;td&gt;+5&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barbare-Unchained.html#POUVOIRDERAGE&quot; title=&quot;Le barbare unchained&quot;&gt;pouvoir de rage&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Barbare-Unchained.html#REDUCTIONDEGATS&quot; title=&quot;Le barbare unchained&quot;&gt;r&#233;duction de d&#233;g&#226;ts&lt;/a&gt; 4/-&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;17&lt;/td&gt;&lt;td&gt;+17/+12/+7/+2&lt;/td&gt;&lt;td&gt;+5&lt;/td&gt;&lt;td&gt;+10&lt;/td&gt;&lt;td&gt;+5&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barbare-Unchained.html#RAGESANSFATIGUE&quot; title=&quot;Le barbare unchained&quot;&gt;rage sans fatigue&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;18&lt;/td&gt;&lt;td&gt;+18/+13/+8/+3&lt;/td&gt;&lt;td&gt;+6&lt;/td&gt;&lt;td&gt;+11&lt;/td&gt;&lt;td&gt;+6&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barbare-Unchained.html#POUVOIRDERAGE&quot; title=&quot;Le barbare unchained&quot;&gt;pouvoir de rage&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Barbare-Unchained.html#SENSDUDANGER&quot; title=&quot;Le barbare unchained&quot;&gt;sens du danger&lt;/a&gt; +6&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;19&lt;/td&gt;&lt;td&gt;+19/+14/+9/+4&lt;/td&gt;&lt;td&gt;+6&lt;/td&gt;&lt;td&gt;+11&lt;/td&gt;&lt;td&gt;+6&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barbare-Unchained.html#REDUCTIONDEGATS&quot; title=&quot;Le barbare unchained&quot;&gt;r&#233;duction de d&#233;g&#226;ts&lt;/a&gt; 5/-&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;20&lt;/td&gt;&lt;td&gt;+20/+15/+10/+5&lt;/td&gt;&lt;td&gt;+6&lt;/td&gt;&lt;td&gt;+12&lt;/td&gt;&lt;td&gt;+6&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barbare-Unchained.html#RAGEDEMAITREBERSERKER&quot; title=&quot;Le barbare unchained&quot;&gt;rage de ma&#238;tre berserker&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Barbare-Unchained.html#POUVOIRDERAGE&quot; title=&quot;Le barbare unchained&quot;&gt;pouvoir de rage&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
